local mover=require("engine.mover_runtime");local loader=require("engine.data.loader");local sessionModule=require("engine.session");local exploration=require("engine.exploration");local savegame=require("engine.savegame")
local p,f=0,0;local function check(v,m)if v then p=p+1;print("  [PASS] "..m)else f=f+1;print("  [FAIL] "..m)end end;local function near(a,b)return math.abs(a-b)<=.0001 end
local raft={id=1,instanceId="event:test-raft",x=2,y=2,mover={type="path",mode="ping_pong",speed=2,dwell=0,carryPlayer=true,waypoints={{x=2,y=2},{x=2,y=6}},footprint={{x=0,y=0}},ports={{inside={x=0,y=0},outside={x=-1,y=0}}},visual={models={open="raft-open.obj",closed="raft-closed.obj"}}}}
local mock={currentMapIndex=99,currentMapData={id=99,events={raft}},moverRuntime={},playerX=2,playerY=3,playerDir="E"};mover.activateMap(mock);local rs=mover.stateForEvent(mock,raft)
check(rs and rs.x==2 and rs.y==2,"generic mover initializes at authored waypoint");check(mover.stepPolicy(mock,3,3)=="allow","authored side port permits boarding");mock.playerX,mock.playerY=3,3;mover.afterPlayerStep(mock);check(rs.onboard==true,"player boards authored footprint");mover.update(mock,.01);check(rs.phase=="moving","zero-dwell mover starts a leg");mover.update(mock,1);check(rs.x==2 and rs.y>2,"generic path advances on Y without X assumptions");local wx,wy=mover.playerWorldRoot(mock);check(wx and wy,"onboard mover exposes smooth world root");check(mover.stepPolicy(mock,mock.playerX,mock.playerY+1)=="block","movement is interlocked in transit")
loader.init();local mi=loader.getMapIndex(32);check(mi~=nil,"metro map registered for persistence fixture");local live=sessionModule.GameSession.new(loader);live:initializeStartingParty();exploration.loadMap(live,mi);local train;for _,v in ipairs(live.currentMapData.events or{})do if v.mover then train=v break end end;check(train~=nil,"metro map exposes mover Event");local st=mover.stateForEvent(live,train);local wp=train.mover.waypoints[st.waypoint];local port=train.mover.ports[2];live.playerX=wp.x+port.outside.x+1;live.playerY=wp.y+port.outside.y+1;live.playerDir="S";check(exploration.moveForward(live),"ordinary movement boards through authored port");check(st.onboard==true,"boarding state owned by mover runtime");mover.update(live,st.timer+.01);if st.phase=="closing"then mover.update(live,(train.mover.door.closeSeconds or 0)+.01)end;mover.update(live,.35);check(st.phase=="moving","save fixture is in active transit");local sx,sy,tm=st.x,st.y,st.timer;local payload=savegame.serialize(live,loader,"map");local restored=savegame.deserialize(payload,loader);local rt;for _,v in ipairs(restored.currentMapData.events or{})do if v.instanceId==train.instanceId then rt=v break end end;local rr=rt and mover.stateForEvent(restored,rt);check(rr and rr.phase=="moving" and rr.onboard==true,"moving/onboard state round-trips through save v6");check(rr and near(rr.x,sx)and near(rr.y,sy)and near(rr.timer,tm),"mover position and timer round-trip exactly");mover.update(restored,.1);check(rr.phase=="moving","restored mover continues same leg");check(mover.playerWorldRoot(restored)~=nil,"restored player retains smooth carry root")
